<?php
namespace Pterodactyl\Services\Nodexa;
use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Http; use RuntimeException;
class FlaxVpsClient { private object $provider; public function __construct(?object $provider=null){$this->provider=$provider?:DB::table('vps_providers')->where('active',true)->first();if(!$this->provider)throw new RuntimeException('Flax VPS provider er ikke konfigureret.');} private function key():string{return Crypt::decryptString($this->provider->api_key);} private function endpoint():string{$url=rtrim((string)$this->provider->endpoint,'/');$url=preg_replace('~/api-endpoint\.php$~i','',$url);return rtrim($url,'/').'/';} public function request(string $action,array $params=[],string $method='POST'):array{$key=$this->key();$url=$this->endpoint();$query=array_merge(['key'=>$key,'action'=>$action],$params);$http=Http::timeout(15)->acceptJson()->withUserAgent('Nodexa-Flax-VPS/1.5');$response=strtoupper($method)==='GET'?$http->get($url,$query):$http->asForm()->post($url,$query);if(!$response->successful())throw new RuntimeException('Flax API HTTP '.$response->status());$json=$response->json();if(!is_array($json))throw new RuntimeException('Ugyldigt svar fra Flax API.');if(($json['success']??true)===false)throw new RuntimeException((string)($json['error']??$json['message']??'Flax API fejl'));if(($json['status']??null)==='error')throw new RuntimeException((string)($json['data']??$json['message']??'Flax API fejl'));return is_array($json['data']??null)?$json['data']:$json;} private function list(array $r,array $keys):array{foreach($keys as $k)if(isset($r[$k])&&is_array($r[$k]))return array_values($r[$k]);return array_is_list($r)?$r:[];} public function servers():array{return $this->list($this->request('user_servers',[],'POST'),['servers','data','result']);}
private function fallbackProducts():array{return [['id'=>1,'productId'=>1,'name'=>'VPS-01','price'=>69.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>2,'productId'=>2,'name'=>'VPS-02','price'=>109.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>3,'productId'=>3,'name'=>'VPS-03','price'=>149.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>4,'productId'=>4,'name'=>'VPS-04','price'=>199.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>5,'productId'=>5,'name'=>'VPS-05','price'=>259.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>6,'productId'=>6,'name'=>'VPS-06','price'=>319.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>7,'productId'=>7,'name'=>'VPS-01+','price'=>99.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>8,'productId'=>8,'name'=>'VPS-02+','price'=>129.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>9,'productId'=>9,'name'=>'VPS-03+','price'=>189.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>10,'productId'=>10,'name'=>'VPS-04+','price'=>219.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>11,'productId'=>11,'name'=>'VPS-05+','price'=>339.00,'currency'=>'DKK','type'=>'VIRTUSION'],['id'=>12,'productId'=>12,'name'=>'VPS-06+','price'=>469.00,'currency'=>'DKK','type'=>'VIRTUSION']];}
public function discoverProducts():array{return $this->fallbackProducts();}
private function fallbackOs():array{return [['id'=>'32','name'=>'Windows Server 2025'],['id'=>'18','name'=>'Windows Server 2022'],['id'=>'19','name'=>'Windows Server 2019'],['id'=>'9','name'=>'Debian 11 (Bullseye) Minimal'],['id'=>'20','name'=>'Debian 11 (Bullseye)'],['id'=>'27','name'=>'Debian 12 (Bookworm)'],['id'=>'7','name'=>'AlmaLinux 8 Minimal'],['id'=>'13','name'=>'AlmaLinux 9 Latest'],['id'=>'2','name'=>'CentOS 7 Minimal'],['id'=>'3','name'=>'CentOS Stream 9'],['id'=>'21','name'=>'Fedora 39 Minimal'],['id'=>'22','name'=>'Fedora 38 Minimal'],['id'=>'8','name'=>'Rocky Linux 8 Minimal'],['id'=>'14','name'=>'Rocky Linux 9 Minimal'],['id'=>'6','name'=>'Ubuntu Server 18.04 LTS'],['id'=>'5','name'=>'Ubuntu Server 20.04 LTS'],['id'=>'11','name'=>'Ubuntu Server 22.04'],['id'=>'31','name'=>'Ubuntu Server 24.04'],['id'=>'24','name'=>'CloudLinux 9 Latest'],['id'=>'25','name'=>'Oracle Linux 9 Minimal'],['id'=>'26','name'=>'Alpine Linux 3.19'],['id'=>'28','name'=>'Arch Linux Latest Minimal']];}
private function normalizeOsList(array $raw):array{$out=[];$walk=function($value,$key=null)use(&$walk,&$out){if(is_array($value)){if(isset($value['id'])||isset($value['template_id'])||isset($value['osid'])||isset($value['os_id'])){$id=(string)($value['id']??$value['template_id']??$value['osid']??$value['os_id']);$name=(string)($value['name']??$value['title']??$value['os_name']??$value['label']??$value['filename']??$id);if($id!=='')$out[$id]=['id'=>$id,'value'=>$id,'template_id'=>$id,'name'=>$name,'label'=>$name]+$value;return;}foreach($value as $k=>$v){if(!is_array($v)&&preg_match('/^\d+$/',(string)$k)){$id=(string)$k;$name=(string)$v;$out[$id]=['id'=>$id,'value'=>$id,'template_id'=>$id,'name'=>$name,'label'=>$name];}else{$walk($v,$k);}}}};$walk($raw);return array_values($out);}
public function discoverOperatingSystems(?string $product=null):array{foreach(['POST','GET'] as $method){try{$raw=$this->request('virtfusion_templates',[],$method);$x=$this->normalizeOsList($raw);if($x)return $x;}catch(\Throwable $e){}try{$raw=$this->request('virtualizor_templates',[],$method);$x=$this->normalizeOsList($raw);if($x)return $x;}catch(\Throwable $e){}}return array_map(fn($x)=>$x+['value'=>$x['id'],'template_id'=>$x['id'],'label'=>$x['name']],$this->fallbackOs());}
public function virtualizorTemplates():array{return $this->discoverOperatingSystems();} public function wispEggs():array{return $this->list($this->request('wisp_eggs',[],'POST'),['eggs','wisp_eggs','data','result']);} public function info(string $id):array{return $this->request('info',['server_id'=>$id],'POST');} public function power(string $id,string $action):array{if(!in_array($action,['boot','shutdown','restart','poweroff'],true))throw new RuntimeException('Ugyldig VPS handling.');return $this->request($action,['server_id'=>$id],'POST');} public function os(string $id):array{return $this->request('os_info',['server_id'=>$id],'POST');} public function rebuild(string $id,string $os):array{return $this->request('build',['server_id'=>$id,'operatingSystem'=>$os],'GET');} public function create(string $productId,string $osId,?string $gameType=null):array{$params=['productId'=>$productId,'operatingSystem'=>$osId];if($gameType!==null&&$gameType!=='')$params['gameType']=$gameType;return $this->request('create',$params,'POST');}}
